update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/toulouse/gironde/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle en Gironde","mecanisme":"La rive droite concentre le port, l''énergie et l''eau. Le Libournais aligne des chais équipés comme des usines, et le massif landais commence par des scieries. Nous avons un hub de techniciens à Bordeaux, et nos équipes couvrent ces trois Girondes avec les mêmes méthodes qu''ailleurs en France.","cta":"Faire chiffrer ma maintenance en Gironde","telephone":"04 78 33 72 05","phraseDelai":"Pour nous joindre : 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Un chargé d''affaires vous rappelle dans l''heure et suit le dossier jusqu''à la clôture."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers qui reviennent contrat après contrat"},{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique et comportemental"},{"valeur":"sur devis","libelle":"point de départ du contrat Zéro arrêt, 6 mois renouvelables, diagnostic gratuit"}]},{"type":"probleme","punchline":"Un broyeur qui s''arrête à Bassens, une ligne d''embouteillage qui casse dans le Libournais. Dans les deux cas, personne sur place ne sait remettre en route avant lundi.","puces":[{"accroche":"Vos ateliers n''ont pas d''équipe maintenance à demeure.","texte":"Dans les Graves ou le Langonnais, l''arrêt se paie comptant, faute de technicien sur site."},{"accroche":"Le bois use tout, vite.","texte":"Scieries, palettes, emballage : coupe, poussière et abrasion attaquent les machines en permanence."},{"accroche":"La rive droite tourne en continu.","texte":"Port, énergie, eau, logistique : un procédé arrêté ne se rattrape pas sur le poste suivant."},{"accroche":"Les chais sont devenus des usines.","texte":"Lignes d''embouteillage, froid, réseaux d''eau, chaudières : un patrimoine technique que le calendrier viticole ne laisse pas entretenir en saison."},{"accroche":"Chercher un prestataire au moment de la panne coûte toujours trop cher.","texte":"Le bon moment pour choisir, c''est avant."}]}]'::jsonb) where path = '/implantations/toulouse/gironde/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Entretien des lignes d''embouteillage et du froid process","texte":", planifié hors saison, dépannage tenu en saison."},"benefice":"La vendange se passe sans arbitrage entre produire et réparer."},{"prestation":{"accroche":"Mécanique lourde pour le bois et l''emballage","texte":"convoyage, outils de coupe, environnements poussiéreux."},"benefice":"Les pièces d''usure sont changées avant la casse, pas après l''arrêt de ligne."},{"prestation":{"accroche":"Procédés continus de la rive droite","texte":"consignations, habilitations électriques, exigences d''environnement."},"benefice":"Les interventions se font dans les règles, sans arrêter plus que nécessaire."},{"prestation":{"accroche":"Électromécanique et automatisme","texte":"moteurs, pompes, ventilateurs, automates SIEMENS et Schneider, via l''[électromécanique](/expertises/electromecanique/) et l''[automatisme](/expertises/automatisme/)."},"benefice":"Un seul intervenant pour le couple mécanique et électrique, sans renvoi de responsabilité."},{"prestation":{"accroche":"Rétrofit chiffré par notre [bureau d''études](/offres/bureau-etudes/)","texte":"quand l''outil vieillit."},"benefice":"La durée de vie de la machine s''allonge, au lieu d''un remplacement à prix fort."},{"prestation":{"accroche":"Technicien intégré à votre équipe","texte":"en [sous-traitance maintenance](/offres/residence/), prise de poste en 2 à 3 semaines."},"benefice":"Le poste est tenu, avec remplacement assuré en cas d''absence."},{"prestation":{"accroche":"Pilotage par les données de votre GMAO","texte":"pannes répétitives, fréquences ajustées, composants critiques en stock."},"benefice":"Vous décidez sur des indicateurs mensuels, pas sur des impressions."}],"prose":[{"texte":"Pour un besoin isolé, le [dépannage industriel](/offres/depannage-industriel/) reste le format le plus simple. Nos techniciens partent avec des outils de diagnostic étalonnés et l''appui technique du groupe derrière eux."}]},{"type":"deroule","etapes":[{"titre":"Le contact","texte":"appel ou demande en ligne, rappel dans l''heure aux horaires ouvrés. Machine, défaut, accès, criticité : la demande se qualifie et un créneau ferme est proposé."},{"titre":"Le chiffrage","texte":"détail ligne à ligne avant tout engagement. Déplacement, temps prévu, pièces au prix du marché, aucune mention en petits caractères."},{"titre":"Le déplacement","texte":"le technicien part avec le plan de prévention validé et l''accueil sécurité préparé. La qualité du geste passe avant la vitesse."},{"titre":"La remise en marche","texte":"diagnostic, réparation, essais électriques et mécaniques."},{"titre":"La traçabilité","texte":"chaque opération consignée dans votre GMAO, données et historique tenus à jour."},{"titre":"Le suivi","texte":"sur un besoin récurrent, les visites se regroupent et les fréquences s''ajustent à l''usage réel du parc."}]},{"type":"garanties","puces":[{"accroche":"Aucun délai routier inventé sur cette page","texte":"le vôtre dépend de votre site, et nous l''annonçons avant de partir. Le rappel dans l''heure, lui, est écrit."},{"accroche":"Un conseil de stock minimal de pièces critiques","texte":"dimensionné sur vos historiques de défaillance et les délais fournisseur. Une grande part des arrêts longs vient d''une pièce absente du magasin."},{"accroche":"Des propos vérifiables","texte":"pas de logo décoratif, pas de référence locale inventée, pas de promesse de délai. Du travail contrôlable, rien d''autre."}]}]'::jsonb) where path = '/implantations/toulouse/gironde/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"cta","question":"Besoin d''un partenaire technique avant la prochaine panne, pas pendant ?","bouton":"Faire chiffrer ma maintenance en Gironde","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Un technicien électromécanicien habilité risque chimique niveau 1, 6 mois de mission","texte":"sur un site de traitement des eaux industrielles","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Un renfort polyvalent sur un parc aux contraintes techniques variées","texte":", papier et emballage, préventif et curatif, de 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Un parc machines de PME diagnostiqué et réparé sans rachat de matériel neuf","texte":"plusieurs solutions chiffrées, adaptées au budget","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Trois techniciens en renfort sur le préventif d''une installation photovoltaïque de grande envergure","texte":", sur plus de six semaines","lienLibelle":"Étude de cas EIFFAGE : partenariat","lienHref":"/preuves/eiffage/"},{"titre":"Le montage complet de portiques de lavage partout en France","texte":"réception, assemblage, levage, raccordements, pour un fabricant qui installe sur tout le territoire","lienLibelle":"Étude de cas ORTHUS x WASHTEC : installation de stations","lienHref":"/preuves/orthus-washtec/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous partout en Gironde, au-delà de Bordeaux ?","reponse":"Oui : Bordeaux Métropole et la rive droite avec Bassens, Lormont et Ambès. Puis le Libournais et l''Entre-deux-Mers, les Graves et le Langonnais, le littoral et le Bassin d''Arcachon. Les départements voisins se traitent au cas par cas, Dordogne, Charente et Landes comprises."},{"question":"Quels délais d''intervention en Gironde ?","reponse":"Aucun chiffre ne sera inventé ici : du nord du département au Sud Gironde, chaque site a son accès et sa criticité. La meilleure réponse reste l''appel, avec rappel dans l''heure aux horaires ouvrés, priorité donnée aux arrêts de production, astreinte 24/24 et 7/7 en option."},{"question":"Respectez-vous nos consignations et nos obligations légales ?","reponse":"Oui : plan de prévention, consignation électrique haute et basse tension, règles de sécurité groupe et normes propres à chaque installation. Travail en hauteur, espaces confinés : les habilitations sont à jour et vérifiées avant l''arrivée."},{"question":"Proposez-vous un technicien à demeure ?","reponse":"Oui, en résidence : un technicien rattaché à Migen, intégré à votre équipe, encadré par un référent qui transmet les comptes rendus. Migen reste l''employeur. En cas d''absence ou de départ, un profil équivalent reprend le poste."},{"question":"Combien coûte une intervention ?","reponse":"Le détail est écrit ligne à ligne avant tout engagement : déplacement, temps prévu, pièces au prix du marché. Pour un besoin récurrent, un contrat et des visites regroupées coûtent moins cher que l''addition des urgences."},{"question":"Vous êtes un annuaire ou un site d''emploi ?","reponse":"Ni l''un ni l''autre. Migen est une entreprise de prestation de services en maintenance industrielle, qui emploie ses propres techniciens. Si vous cherchez un poste, nos [métiers de la maintenance](/carriere/) détaillent le parcours et la sélection."}]}]'::jsonb) where path = '/implantations/toulouse/gironde/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"ctaFinal","question":"Besoin de fiabiliser un parc réparti sur plusieurs sites du département ?","bouton":"Faire chiffrer ma maintenance en Gironde","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/toulouse/gironde/';
